from admissions_records import *
ALL=['reading','writing','listening','speaking']
def eng(min,variant=None,sections=None,old=None,new=None,waiver=None,alternatives=None,note=None):
 e={'requirement':'required-unless-exempt','ielts':{'accepted':True,'min':min,'variant':variant,'role':'admission'}}
 if sections is not None:e['ielts']['sections']=dict.fromkeys(ALL,sections)
 if old is not None or new is not None:e['toefl']={'accepted':True,'scales':([{'period':'pre2026','min':old}] if old is not None else [])+([{'period':'post2026','min':new}] if new is not None else [])}
 for k,v in [('waiver',waiver),('alternatives',alternatives),('note',note)]:
  if v:e[k]=v
 return e
def source(url,en,ru):return S(url,L(en,ru))
UNKNOWN=L('Academic SAT/ACT rules for all international school qualifications were not established. A US-curriculum rule is not applied to every international applicant.','Академические правила SAT/ACT для всех иностранных школьных квалификаций не установлены. Правило учебной программы США не применяется ко всем иностранцам.')
def save(id,routes,change,gaps=None):record(id,routes,change,gaps or ['Fall 2027-specific applicability and academic requirements for the exact school qualification require confirmation.'])

